"""The deterministic run loop, following the normative per-tick order."""

from units import BIRD_X, PIPE_W, GLIDE_VY, SPAWN_EVERY
from physics import step_bird
from world import spawn, scroll, cull
from collide import pipe_hit


def _tick(t, y, vy, score, alive, pipes, s, flap):
    """Execute one tick (steps 1-6). Returns the updated state tuple."""
    if t % SPAWN_EVERY == 0:
        s, pipe = spawn(t, s)
        if pipe is not None:
            pipes.append(pipe)
    y, vy, alive = step_bird(y, vy, flap)
    scroll(pipes)
    for p in pipes:
        if alive and pipe_hit(y, p):
            alive = False
    if alive:
        for p in pipes:
            if not p["passed"] and p["x"] + PIPE_W <= BIRD_X:
                p["passed"] = True
                score += 1
                if abs(vy) <= GLIDE_VY:
                    score += 1
    pipes = cull(pipes)
    return y, vy, score, alive, pipes, s


def run(seed, ticks, flaps="0", powerups=False):
    """Run the simulation. Returns a state dict (see spec/00)."""
    y, vy, score, alive = 560, 0, 0, True
    pipes, s, ticks_run = [], seed, 0
    for t in range(ticks):
        if not alive:
            break
        flap = flaps[t % len(flaps)] == "1"
        y, vy, score, alive, pipes, s = _tick(
            t, y, vy, score, alive, pipes, s, flap)
        ticks_run += 1
    state = {"y": y, "vy": vy, "score": score,
             "alive": alive, "ticks_run": ticks_run}
    return state

"""Command line for flapsim: hand-rolled argv parsing and output."""

import sys
from engine import run


def parse(argv):
    """Parse --seed/--ticks/--flaps by hand. Returns (seed, ticks, flaps)."""
    seed, ticks, flaps = 0, 0, "0"
    i = 0
    while i < len(argv):
        if argv[i] == "--seed":
            seed = int(argv[i + 1]); i += 2
        elif argv[i] == "--ticks":
            ticks = int(argv[i + 1]); i += 2
        elif argv[i] == "--flaps":
            flaps = argv[i + 1]; i += 2
        else:
            raise SystemExit("unknown flag: " + argv[i])
    return seed, ticks, flaps


def trace(t, y, vy, score, alive):
    return ("TRACE t=%04d y=%04d vy=%+05d score=%02d alive=%d"
            % (t, y, vy, score, 1 if alive else 0))


def digest(seed, ticks, st):
    return ("DIGEST seed=%d ticks=%d score=%02d alive=%d y=%04d vy=%+05d "
            "ticks_run=%d" % (seed, ticks, st["score"],
                              1 if st["alive"] else 0, st["y"], st["vy"],
                              st["ticks_run"]))


def main(argv):
    if len(argv) == 2 and argv[1] == "--selfcheck":
        return selfcheck()
    seed, ticks, flaps = parse(argv[1:])
    every = max(1, ticks // 20)
    y, vy, score, alive = 560, 0, 0, True
    for t in range(ticks):
        if not alive:
            break
        st = run(seed, t + 1, flaps)
        if (t + 1) % every == 0 or not st["alive"]:
            print(trace(t, st["y"], st["vy"], st["score"], st["alive"]))
    final = run(seed, ticks, flaps)
    print(digest(seed, ticks, final))


def selfcheck():
    cases = [(7, 200, "0010", 8, 1), (7, 120, "01", 0, 0),
             (3, 200, "0001", 8, 1), (11, 60, "1", 0, 0),
             (2, 90, "0", 0, 0), (5, 200, "0010", 8, 1)]
    for i, (seed, ticks, flaps, escore, ealive) in enumerate(cases, 1):
        st = run(seed, ticks, flaps)
        ok = st["score"] == escore and (1 if st["alive"] else 0) == ealive
        print("EX%d seed=%d ticks=%d flaps=%s expect score=%02d alive=%d "
              "got score=%02d alive=%d %s"
              % (i, seed, ticks, flaps, escore, ealive, st["score"],
                 1 if st["alive"] else 0, "OK" if ok else "FAIL"))


if __name__ == "__main__":
    main(sys.argv)

